package com.trainflow.pricing; import com.trainflow.program.*;import com.trainflow.shared.error.ApiError;import com.trainflow.trainingcase.*;import java.math.*;import java.time.Instant;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PricingService {private static final Set<BigDecimal> VAT=Set.of(new BigDecimal("19.000"),new BigDecimal("13.000"),new BigDecimal("7.000"),new BigDecimal("0.000"));private final TrainingPricingRepository pricings;private final TrainingCaseRepository cases;private final TrainingProgramRepository programs;private final ActivityRepository activities;public PricingService(TrainingPricingRepository p,TrainingCaseRepository c,TrainingProgramRepository programs,ActivityRepository a){pricings=p;cases=c;this.programs=programs;activities=a;}@Transactional(readOnly=true)public PricingResponse get(UUID id){caseEntity(id);return response(pricing(id));}@Transactional public PricingResponse create(UUID id){TrainingCase c=mutableCase(id);if(pricings.findByTrainingCaseId(id).isPresent())throw conflict("TRAINING_PRICING_ALREADY_EXISTS","Une tarification existe déjà pour ce dossier.");if(c.getStatus()!=TrainingCaseStatus.PROGRAMME_VALIDE)invalid();if(c.getTrainer()==null)throw conflict("TRAINER_REQUIRED","Un formateur doit être affecté.");TrainingProgram p=programs.findByTrainingCaseId(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_PROGRAM_NOT_FOUND","Le programme est introuvable."));if(!p.isValidated())throw conflict("TRAINING_PROGRAM_NOT_VALIDATED","Le programme doit être validé.");TrainingPricing x=new TrainingPricing(id);int minutes=duration(p),dayCount=p.getDays().size();x.setProgramDayCountSnapshot(dayCount);x.setProgramDurationMinutesSnapshot(minutes);x.setTrainerDailyRateSnapshot(money(c.getTrainer().getDailyRate()));x.setTrainerHourlyRateSnapshot(money(c.getTrainer().getHourlyRate()));if(c.getTrainer().getDailyRate()!=null){x.setTrainerCost(money(c.getTrainer().getDailyRate().multiply(BigDecimal.valueOf(dayCount))));x.setInitializationMethod(TrainerCostInitializationMethod.DAILY_RATE);}else if(c.getTrainer().getHourlyRate()!=null){x.setTrainerCost(money(c.getTrainer().getHourlyRate().multiply(BigDecimal.valueOf(minutes)).divide(BigDecimal.valueOf(60),6,RoundingMode.HALF_UP)));x.setInitializationMethod(TrainerCostInitializationMethod.HOURLY_RATE);}else{x.setInitializationMethod(TrainerCostInitializationMethod.NONE);}pricings.saveAndFlush(x);c.setStatus(TrainingCaseStatus.TARIFICATION_EN_PREPARATION);log(c,x,"TrainingPricingCreated");return response(x);}@Transactional public PricingResponse update(UUID id,PricingRequest r){var pair=editable(id);TrainingPricing p=pair.p;if(r.trainerCost()!=null)p.setTrainerCost(money(r.trainerCost()));if(r.transportCost()!=null)p.setTransportCost(money(r.transportCost()));if(r.roomCost()!=null)p.setRoomCost(money(r.roomCost()));if(r.mealCost()!=null)p.setMealCost(money(r.mealCost()));if(r.otherCost()!=null)p.setOtherCost(money(r.otherCost()));if(r.marginRate()!=null)p.setMarginRate(rate(r.marginRate()));if(r.vatRate()!=null)p.setVatRate(rate(r.vatRate()));if(r.vatExemptionReason()!=null)p.setVatExemptionReason(clean(r.vatExemptionReason()));if(r.vatLegalReference()!=null)p.setVatLegalReference(clean(r.vatLegalReference()));validateVat(p);return response(p);}@Transactional public PricingResponse submit(UUID id){var pair=editable(id);validateFinancials(pair.p);pair.p.setSubmitted(true);pair.p.setSubmittedAt(Instant.now());pair.p.setReturnReason(null);pair.c.setStatus(TrainingCaseStatus.TARIFICATION_A_VALIDER);return response(pair.p);}@Transactional public PricingResponse back(UUID id,String reason){TrainingCase c=mutableCase(id);TrainingPricing p=locked(id);if(c.getStatus()!=TrainingCaseStatus.TARIFICATION_A_VALIDER||p.isValidated())invalid();p.setSubmitted(false);p.setSubmittedAt(null);p.setReturnedAt(Instant.now());p.setReturnReason(required(reason));c.setStatus(TrainingCaseStatus.TARIFICATION_EN_PREPARATION);return response(p);}@Transactional public PricingResponse validate(UUID id){TrainingCase c=mutableCase(id);TrainingPricing p=locked(id);if(p.isValidated())throw conflict("TRAINING_PRICING_ALREADY_VALIDATED","La tarification est déjà validée.");if(c.getStatus()!=TrainingCaseStatus.TARIFICATION_A_VALIDER||!p.isSubmitted())invalid();validateFinancials(p);p.setValidated(true);p.setValidatedAt(Instant.now());c.setStatus(TrainingCaseStatus.TARIFICATION_VALIDEE);return response(p);}private Pair editable(UUID id){TrainingCase c=mutableCase(id);TrainingPricing p=locked(id);if(c.getStatus()!=TrainingCaseStatus.TARIFICATION_EN_PREPARATION||p.isSubmitted()||p.isValidated())throw conflict("TRAINING_PRICING_NOT_EDITABLE","La tarification n’est pas modifiable dans son état actuel.");return new Pair(c,p);}private void validateFinancials(TrainingPricing p){validateVat(p);if(totals(p)[0].signum()<=0)throw new ApiError(HttpStatus.BAD_REQUEST,"TRAINING_PRICING_EMPTY","La tarification doit contenir un montant strictement positif.");}private void validateVat(TrainingPricing p){if(!VAT.contains(rate(p.getVatRate())))throw new ApiError(HttpStatus.BAD_REQUEST,"TRAINING_PRICING_INVALID_VAT_RATE","Le taux de TVA sélectionné n’est pas autorisé.");if(rate(p.getVatRate()).signum()==0&&clean(p.getVatExemptionReason())==null&&clean(p.getVatLegalReference())==null)throw new ApiError(HttpStatus.BAD_REQUEST,"VAT_EXEMPTION_JUSTIFICATION_REQUIRED","Une justification ou une référence fiscale est obligatoire pour une TVA à 0 %.");}private BigDecimal[]totals(TrainingPricing p){BigDecimal costs=money(p.getTrainerCost().add(p.getTransportCost()).add(p.getRoomCost()).add(p.getMealCost()).add(p.getOtherCost()));BigDecimal margin=money(costs.multiply(p.getMarginRate()).divide(BigDecimal.valueOf(100)));BigDecimal ht=money(costs.add(margin));BigDecimal vat=money(ht.multiply(p.getVatRate()).divide(BigDecimal.valueOf(100)));return new BigDecimal[]{costs,margin,ht,vat,money(ht.add(vat))};}private PricingResponse response(TrainingPricing p){BigDecimal[]t=totals(p);return new PricingResponse(p.getId(),p.getTrainingCaseId(),p.getCurrency(),money(p.getTrainerCost()),money(p.getTransportCost()),money(p.getRoomCost()),money(p.getMealCost()),money(p.getOtherCost()),rate(p.getMarginRate()),t[1],t[0],t[2],rate(p.getVatRate()),t[3],t[4],p.getVatExemptionReason(),p.getVatLegalReference(),p.getTrainerDailyRateSnapshot(),p.getTrainerHourlyRateSnapshot(),p.getProgramDayCountSnapshot(),p.getProgramDurationMinutesSnapshot(),p.getInitializationMethod(),p.isSubmitted(),p.getSubmittedAt(),p.isValidated(),p.getValidatedAt(),p.getReturnedAt(),p.getReturnReason(),!p.isSubmitted()&&!p.isValidated(),p.getCreatedAt(),p.getUpdatedAt());}private int duration(TrainingProgram p){int total=0;for(TrainingProgramDay d:p.getDays())for(TrainingProgramItem i:d.getItems())if(d.getItems().stream().noneMatch(x->i.getId().equals(x.getParentId())))total+=i.getTheoryMinutes()+i.getPracticeMinutes();return total;}private TrainingCase mutableCase(UUID id){TrainingCase c=cases.locked(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_CASE_NOT_FOUND","Le dossier est introuvable."));if(c.isArchived()||c.getStatus()==TrainingCaseStatus.ANNULE)throw conflict("TRAINING_CASE_NOT_EDITABLE","Le dossier ne peut plus être modifié.");return c;}private TrainingCase caseEntity(UUID id){return cases.detailed(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_CASE_NOT_FOUND","Le dossier est introuvable."));}private TrainingPricing pricing(UUID id){return pricings.findByTrainingCaseId(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_PRICING_NOT_FOUND","La tarification est introuvable."));}private TrainingPricing locked(UUID id){return pricings.locked(id).orElseThrow(()->new ApiError(HttpStatus.NOT_FOUND,"TRAINING_PRICING_NOT_FOUND","La tarification est introuvable."));}private void log(TrainingCase c,TrainingPricing p,String action){activities.save(new ActivityLog(admin(),c.getId(),action,"training_pricing",p.getId(),Map.of()));}private UUID admin(){return UUID.fromString(SecurityContextHolder.getContext().getAuthentication().getName());}private BigDecimal money(BigDecimal v){return v==null?null:v.setScale(3,RoundingMode.HALF_UP);}private BigDecimal rate(BigDecimal v){return v.setScale(3,RoundingMode.HALF_UP);}private String clean(String s){return s==null||s.trim().isEmpty()?null:s.trim();}private String required(String s){String v=clean(s);if(v==null)throw new ApiError(HttpStatus.BAD_REQUEST,"RETURN_REASON_REQUIRED","Le motif du retour est obligatoire.");return v;}private ApiError conflict(String c,String m){return new ApiError(HttpStatus.CONFLICT,c,m);}private void invalid(){throw conflict("INVALID_TRAINING_CASE_STATUS","Le statut du dossier ne permet pas cette action.");}private record Pair(TrainingCase c,TrainingPricing p){}
}
